18:const OPINION_ERROR = [...BANNED, 'we believe', 'we think', 'we expect', 'we suspect', 'in our view', 'in our opinion', 'our take', 'our read', 'clearly', 'obviously', 'undoubtedly', 'no doubt', 'it is likely', "it's likely", 'is likely to', 'are likely to', 'in all likelihood', 'all but certain', 'inevitable', 'inevitably', 'it seems', 'seems to', 'appears to be', 'arguably', 'the real story', 'the takeaway', 'bottom line', 'make no mistake', 'read between the lines', 'could signal', 'may signal', 'game-changing'];
19:const OPINION_WARN = ['likely', 'suggests that', 'suggest that', 'signals that', 'signal that', 'should', 'must', 'could', 'might', 'notably', 'importantly', 'interestingly', 'worrying', 'alarming', 'concerning', 'striking', 'remarkable', 'landmark', 'watershed', 'unprecedented', 'historic'];
20-// A sentence that asserts a cause must attribute it to someone who said so.
21:const CAUSAL_RE = /\b(because|led to|leads to|caused|causes|driven by|in response to|as a result|resulted in|due to|prompted|triggered|in reaction to|therefore|consequently|explains why|is why|to counter|retaliat\w*)\b/i;
22:const ATTRIBUTION_RE = /\b(said|says|wrote|writes|told|according to|reported|reports|argued|argues|stated|states|attributed|attributes|cited|cites|citing|described|describes|filing|announced|testified)\b/i;
23-
24-const NUM_RE = /\d[\d,]*(?:\.\d+)?/g;
25-const normNum = (n) => n.replace(/,/g, '').replace(/\.0+$/, '');
26-const digitsOf = (text) => new Set((String(text).replace(/,/g, '').match(/\d+(?:\.\d+)?/g) || []).map(normNum));
27-
28-const escapeRe = (s) => s.replace(/[-/\\^$*+?.()|[\]{}]/g, '\\$&');
29-// Phrases from `list` found in `text` (word-bounded, case-insensitive).
30-const bannedHits = (text, list) => list.filter((w) => new RegExp(`\\b${escapeRe(w)}\\b`, 'i').test(text));
