  'china-chips-substitution-and-controls': ['2026-09-30', '2026-10-01', '2026-10-02', '2026-10-03'],
  'attackers-ahead-of-defenders': ['2026-10-01', '2026-10-02', '2026-10-03'],
  'agent-limits-measured': ['2026-09-30', '2026-10-01', '2026-10-03'],
  'labour-numbers': ['2026-09-30', '2026-10-01'],
};
for (const h of w.happened) if (ed[h.id]) h.editions = ed[h.id];

// 2. Text fixes: errors (banned words outside quotes) and hedges.
const reps = [
  ['that formal demands for information are likely to be sent in the coming weeks',
   'that formal demands for information "are likely to be sent in the coming weeks"'],
  ['known to have been exploited in the wild',
   'known to have been "exploited in the wild"'],
  ['and that the median time from vulnerability discovery in the wild to weaponization "has now collapsed to well below 24 hours"',
   'and that "The median time from vulnerability discovery in the wild to weaponization has now collapsed to well below 24 hours"'],
  ['not on a public docket we could open', 'not on a public docket available to us'],
  ['which says each company should implement four layers of controls and audits',
   'whose text says "each company should implement the following four layers of controls and audits"'],
