  ['half of likely AI-discovered vulnerabilities enable remote code execution',
   'half of "likely AI-discovered" vulnerabilities enable remote code execution'],
  ['a study finding robots could perform 74% of US physical tasks',
   'a study finding robots "could perform" 74% of US physical tasks'],
  ['the Medicare access on 18 June was announced in late September',
   'the Medicare access in June was announced in late September'],
];

// 3. Give the connection its figure a home: add the Bloomberg Intelligence
//    measurement to the China item, which is where it belongs.
const china = w.happened.find((h) => h.id === 'china-chips-substitution-and-controls');
china.bullets[4] = china.bullets[4].replace(
  'Huawei published no sales figure behind Xu’s claim.',
  'Huawei published no sales figure behind Xu’s claim. On 4 October Bloomberg Intelligence put the top US and Chinese models 2.3 LiveBench points apart, down from about 9% in May.'
);
