let s = JSON.stringify(w, null, 2);
let n = 0;
for (const [a, b] of reps) {
  if (s.includes(a)) { s = s.split(a).join(b); n++; } else console.log('NOT FOUND:', a.slice(0, 70));
}
fs.writeFileSync(p, s + '\n');
console.log('text fixes applied:', n, 'of', reps.length);

