const fs = require('fs');
const p = '/home/user/ainews/data/2026-10-05.week.json';
let s = fs.readFileSync(p, 'utf8');

// The previous pass inserted raw double quotes into JSON string values.
// Escape exactly those inserted spans.
const spans = [
  '"are likely to be sent in the coming weeks"',
  '"exploited in the wild"',
  '"each company should implement the following four layers of controls and audits"',
  '"likely AI-discovered"',
  '"could perform"',
];
let n = 0;
for (const raw of spans) {
  const esc = raw.replace(/"/g, '\\"');
  if (s.includes(raw)) { s = s.split(raw).join(esc); n++; }
}
fs.writeFileSync(p, s);
console.log('escaped spans:', n);

// Now parse and apply the one remaining text fix on the object itself.
const w = JSON.parse(fs.readFileSync(p, 'utf8'));
const mdr = w.happened.find((h) => h.id === 'attackers-ahead-of-defenders');
const before = 'and that the median time from vulnerability discovery in the wild to weaponization "has now collapsed to well below 24 hours"';
const after = 'and that "The median time from vulnerability discovery in the wild to weaponization has now collapsed to well below 24 hours"';
let hit = false;
mdr.bullets = mdr.bullets.map((b) => { if (b.includes(before)) { hit = true; return b.split(before).join(after); } return b; });
console.log('mdr bullet fix:', hit);
fs.writeFileSync(p, JSON.stringify(w, null, 2) + '\n');
console.log('ok');

