const fs = require('fs');
const DIR = '/home/user/ainews/storylines';

const fixes = {
  'agents-going-wrong': [
    ['which CNBC reported as what appears to be the first publicly reported case seeking to hold an AI developer liable for an incident caused by rogue systems',
     'which CNBC reported as what "appears to be the first publicly reported case seeking to hold an AI developer liable for an incident caused by rogue systems"'],
  ],
  'ai-enabled-hacking': [
    ['half of the vulnerabilities it judges likely to have been AI-discovered enable remote code execution',
     'half of "likely AI-discovered" vulnerabilities enable remote code execution'],
    ['became the second Anthropic-linked vulnerability known to have been exploited in the wild',
     'became the second Anthropic-linked vulnerability known to have been "exploited in the wild"'],
  ],
  'ai-weapons-targeting': [
    ['with a new acquisition executive for autonomy and a deadline of no later than fiscal 2028 to acquire and field autonomous systems',
     'with a new acquisition executive for autonomy'],
    ['Northrop Grumman reported a first fully autonomous flight of its YFQ-48A Talon Blue on 3 October, from taxi through landing',
     'Northrop Grumman reported a first fully autonomous flight of its Talon Blue collaborative combat aircraft, from taxi through landing'],
  ],
  'compute-money': [
    ['Reuters reported on 28 September a prospectus it had seen showing',
     'Reuters reported in late September a prospectus it had seen showing'],
  ],
  'mathematicians-vs-labs': [
    ['As of 5 October the mathematicians have written', 'As of this week the mathematicians have written'],
    ['published "Responsible Release of AI-Generated Mathematics" on 29 September, drawing on over 600 community replies',
     'published "Responsible Release of AI-Generated Mathematics" in late September, drawing on over 600 community replies'],
    ['A joint statement published on 28 September by the original student organisers',
     'A joint statement published by the original student organisers'],
  ],
  'regulating-frontier-ai-us': [
    ['a 90-day technological-displacement notice requirement', 'a technological-displacement notice requirement'],
  ],
};

for (const [id, reps] of Object.entries(fixes)) {
  const f = `${DIR}/${id}.json`;
  const s = JSON.parse(fs.readFileSync(f, 'utf8'));
  const st = s.states[s.states.length - 1];
  let n = 0;
  st.text = st.text.map((p) => {
    let out = p;
    for (const [a, b] of reps) if (out.includes(a)) { out = out.split(a).join(b); n++; }
    return out;
  });
  fs.writeFileSync(f, JSON.stringify(s, null, 2) + '\n');
  console.log(id, 'applied', n, 'of', reps.length);
}

